contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint extra) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        c.getFirstWithdrawalBonus(address(this)); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(this).balance;

        bool reverted;
        c.withdrawReward(address(this)); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted == (balanceBefore < 100));
    }

    receive() external payable {}
}

