// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(uint256 extra) internal {
        vm.deal(address(c), VALUE_CAP);
        try c.getFirstWithdrawalBonus(address(this)) {} catch { return; }
        uint balanceBefore = address(this).balance;
        bool reverted;
        try c.withdrawReward(address(this)) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted == (balanceBefore < 100));
    }

    function testFuzz_run(uint256 extra) public {
        _run(extra);
    }

    receive() external payable {}
}
